#include <set>
#include <iostream>

int main() {
    std::set<int> coll1;
    coll1.insert(4);

    // Successful insertion
    auto status1 = coll1.insert(8);
    if (status1.second) {
        std::cout << "8 inserted.\n";
    }

    // Failed insertion (duplicate)
    auto status2 = coll1.insert(8);
    if (!status2.second) {
        std::cout << "8 already exists. Iterator points to: " 
                  << *status2.first << "\n";
    }
}
